y = P_y.gen()

def deterministic_sqrt(val):
    return min(val.sqrt(all=True))

def select0(E0, b0):
    torsion_points = sorted(E0.torsion_polynomial(_sage_const_2 ).roots(multiplicities=False))
    if b0:
        return torsion_points[-_sage_const_1 ], torsion_points[_sage_const_1 ]
    else:
        return torsion_points[_sage_const_1 ], torsion_points[-_sage_const_1 ]

def select(lambda0, lambda1, b):
    if b:
        return max(lambda0, lambda1)
    else:
        return min(lambda0, lambda1)

def next_curve(A, alpha, b):
    xi = alpha**_sage_const_2 
    zeta = _sage_const_3  * xi + A
    eta = deterministic_sqrt(zeta)
    new_A = -(_sage_const_4  * A + _sage_const_15  * xi)
    lambda0 = alpha + _sage_const_2  * eta
    lambda1 = alpha - _sage_const_2  * eta
    new_alpha = select(lambda0, lambda1, b)
    return new_A, new_alpha

def data_to_bits(data):
    # data ở đây là bytes
    bits = [int(b) for c in data for b in "{:08b}".format(c)]
    assert bits and all(b in (_sage_const_0 , _sage_const_1 ) for b in bits)
    return bits

def cgl_forward(E_start, bits):
    """Đi xuôi đồ thị để tìm đường cong đích."""
    A_curr = E_start.a4()
    alpha_curr, _ = select0(E_start, bits[_sage_const_0 ])
    for b in bits[_sage_const_1 :]:
        A_curr, alpha_curr = next_curve(A_curr, alpha_curr, b)
    
    xi = alpha_curr**_sage_const_2 
    new_A = -(_sage_const_4  * A_curr + _sage_const_15  * xi)
    new_B = -alpha_curr * (_sage_const_8  * A_curr + _sage_const_22  * xi)
    return EllipticCurve(K, [new_A, new_B])

def backtrack(A_curr, alpha_curr, bit_idx, bits):
    """Hàm đi lùi tìm gốc E0 (tối ưu hóa phương trình bậc 2)."""
    if bit_idx == _sage_const_0 :
        B0 = -alpha_curr**_sage_const_3  - A_curr * alpha_curr
        E0 = EllipticCurve(K, [A_curr, B0])
        alpha_test, _ = select0(E0, bits[_sage_const_0 ])
        if alpha_test == alpha_curr:
            return E0
        return None

    b = bits[bit_idx]
    eq = _sage_const_4 *(y**_sage_const_2 ) - _sage_const_2 *alpha_curr*y + (alpha_curr**_sage_const_2  + A_curr)
    candidates = eq.roots(multiplicities=False)
    
    for alpha_old_cand in candidates:
        A_old_cand = (-A_curr - _sage_const_15  * (alpha_old_cand**_sage_const_2 )) / _sage_const_4 
        try:
            t_A, t_alpha = next_curve(A_old_cand, alpha_old_cand, b)
            if t_A == A_curr and t_alpha == alpha_curr:
                result = backtrack(A_old_cand, alpha_old_cand, bit_idx - _sage_const_1 , bits)
                if result is not None:
                    return result
        except ValueError:
            continue
    return None

def find_bridge_bfs(E_forward, E_split, max_bytes=_sage_const_3 ):
    """
    BFS để tìm chuỗi đệm nối từ E_forward quay về E_split (tạo thành chu trình).
    """
    print(f"    [*] Đang chạy BFS tìm cầu nối độ dài {max_bytes} bytes...")
    target_A = E_split.a4()
    
    # Duyệt qua các tổ hợp byte đệm
    for pad_bytes in product(range(_sage_const_256 ), repeat=max_bytes):
        # Loại trừ \n và \r để không làm gãy cấu trúc comment của Python
        if _sage_const_0x0a  in pad_bytes or _sage_const_0x0d  in pad_bytes:
            continue
            
        pad_bits = data_to_bits(bytes(pad_bytes))
        
        try:
            E_test = cgl_forward(E_forward, pad_bits)
            if E_test.a4() == target_A:
                return bytes(pad_bytes)
        except Exception:
            continue
            
    return None

